<template>
  <div class="page wishlist-page">
    <PageHeader title="心愿单" subtitle="管理购买意向、预算和价格观察。"><PrimaryButton label="添加心愿" :icon="plusIcon" @click="openEditor()" /></PageHeader>
    <AsyncState :loading="loading" :error="error" :empty="items.length===0" empty-title="还没有购买计划" empty-text="记录目标价和优先级，等待合适的购买时机。" @retry="load"><template #empty-action><PrimaryButton label="添加心愿" :icon="plusIcon" @click="openEditor()" /></template>
      <section class="dark-card summary-banner"><div class="lead"><span>计划预算</span><strong>{{ money(totalBudget) }}</strong></div><p>已规划 {{ pendingItems.length }} 件物品</p><p class="lime">其中 {{ highPriority }} 件高优先级</p><div class="budget-progress"><span>目标价覆盖率 {{ priceCoverage }}%</span><div class="progress-track"><div class="progress-fill" :style="progressStyle(priceCoverage)"></div></div></div></section>
      <div class="wishlist-tabs"><button :class="{active: statusFilter==='全部'}" @click="statusFilter='全部'">全部 {{items.length}}</button><button :class="{active: statusFilter==='未购买'}" @click="statusFilter='未购买'">计划中 {{pendingItems.length}}</button><button :class="{active: statusFilter==='已购买'}" @click="statusFilter='已购买'">已购买 {{purchasedItems.length}}</button><el-input v-model="keyword" placeholder="搜索心愿" clearable /></div>
      <section class="card wishlist-table"><div class="wishlist-heading"><div><h2>心愿清单</h2><span>按创建时间倒序排列</span></div><div class="view-tools"><span>{{ sortedItems.length }} 条记录</span><button class="view-switch" @click="viewMode=viewMode==='list'?'thumbnail':'list'">{{viewMode==='list'?'缩略图模式':'列表模式'}} <b>⇄</b></button></div></div><template v-if="viewMode==='list'"><div class="wish-row wish-head"><span>名称</span><span>创建时间</span><span>分类</span><span>品牌</span><span>心愿来源</span><span>关注最新价格</span><span>状态</span><span></span></div><button v-for="item in sortedItems" :key="item.id" class="wish-row" @click="openDetail(item)"><span class="wish-name"><img v-if="item.imageUrl" :src="item.imageUrl" :alt="item.name"><strong>{{item.name}}</strong><small>{{item.model||'—'}}</small></span><time>{{formatDate(item.createdAt)}}</time><span class="truncate">{{item.categoryName||'未分类'}}</span><span class="truncate">{{item.brandName||'—'}}</span><span class="truncate">{{item.source||'—'}}</span><span class="price-cell"><b>{{money(item.currentPrice)}}</b><small v-if="item.lastPriceAt">{{formatDate(item.lastPriceAt)}}</small></span><span class="tag" :class="{done:item.status==='已购买'}">{{item.status==='已购买'?'已购买':'心愿中'}}</span><span class="row-more" @click.stop><el-dropdown trigger="click"><button class="text-button">操作</button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="item.status!=='已购买'" @click="openPrice(item)">更新关注价格</el-dropdown-item><el-dropdown-item @click="openHistory(item)">价格历史</el-dropdown-item><el-dropdown-item v-if="item.status!=='已购买'" @click="openPurchase(item)">标记已购买</el-dropdown-item><el-dropdown-item v-if="item.convertedAssetId" @click="router.push(`/assets/${item.convertedAssetId}`)">查看已购物品</el-dropdown-item><el-dropdown-item divided @click="remove(item)">删除心愿</el-dropdown-item></el-dropdown-menu></template></el-dropdown></span></button></template><section v-else class="wish-thumbnail-grid"><button v-for="item in sortedItems" :key="item.id" class="wish-thumbnail" @click="openDetail(item)"><div class="thumbnail-image"><img v-if="item.imageUrl" :src="item.imageUrl" :alt="item.name"><strong v-else>{{initials(item.name)}}</strong><span class="tag" :class="{done:item.status==='已购买'}">{{item.status==='已购买'?'已购买':'心愿中'}}</span></div><div><strong>{{item.name}}</strong><p>{{item.categoryName||'未分类'}} · {{item.brandName||'未填写品牌'}}</p><b>{{money(item.currentPrice)}}</b><small>{{formatDate(item.createdAt)}} 创建</small></div></button></section><div v-if="!sortedItems.length" class="table-empty">未找到匹配的心愿</div></section>
    </AsyncState>

    <el-dialog v-model="editorOpen" :title="editing ? '编辑心愿' : '添加心愿'" width="720px" class="wishlist-editor-dialog"><el-form label-position="top" class="dialog-form wishlist-editor-form"><div class="dialog-grid"><el-form-item label="名称" required><el-input v-model="wishForm.name" placeholder="例如：Sony WH-1000XM6" /></el-form-item><el-form-item label="优先级"><el-select v-model="wishForm.priority"><el-option label="高优先级" :value="3"/><el-option label="中优先级" :value="2"/><el-option label="低优先级" :value="1"/></el-select></el-form-item><el-form-item label="目标价"><el-input-number v-model="wishForm.expectedPrice" :min="0" :precision="2" /></el-form-item><el-form-item label="首次关注价格"><el-input-number v-model="wishForm.currentPrice" :min="0" :precision="2" placeholder="当前价格" /></el-form-item><el-form-item label="分类"><QuickCategorySelect v-model="wishForm.categoryId" :categories="categories" @created="addCategory" /></el-form-item><el-form-item label="品牌"><QuickBrandSelect v-model="wishForm.brandId" :brands="brands" @created="addBrand" /></el-form-item><el-form-item class="wide-field" label="型号"><el-input v-model="wishForm.model" /></el-form-item></div><el-form-item label="心愿图片"><div class="wish-upload"><img v-if="wishForm.imageUrl" :src="wishForm.imageUrl" alt="心愿图片"/><AttachmentDropzone accept="image/*" :multiple="false" compact label="上传图片" hint="拖拽、点击或粘贴图片" :disabled="uploading" @files="uploadCover"/></div></el-form-item><div class="dialog-grid"><el-form-item label="商品链接"><el-input v-model="wishForm.link" /></el-form-item><el-form-item label="心愿来源"><el-input v-model="wishForm.source" placeholder="朋友推荐、评测视频、线下体验…" /></el-form-item></div><el-form-item label="备注"><el-input v-model="wishForm.notes" type="textarea" :rows="3" /></el-form-item></el-form><template #footer><div class="wishlist-editor-actions"><button class="secondary-button" @click="editorOpen=false">取消</button><PrimaryButton label="保存心愿" :loading="saving" @click="saveWish" /></div></template></el-dialog>
    <el-dialog v-model="priceOpen" title="记录当前价格" width="430px"><el-form label-position="top" class="dialog-form"><el-form-item label="当前价格"><el-input-number v-model="currentPrice" :min="0" :precision="2" /></el-form-item></el-form><template #footer><button class="secondary-button" @click="priceOpen=false">取消</button><PrimaryButton label="保存价格" :loading="saving" @click="savePrice" /></template></el-dialog>
    <el-dialog v-model="historyOpen" title="价格历史" width="560px"><div v-if="historyLoading" class="small-loading">正在加载…</div><div v-else-if="history.length" class="history-list"><div v-for="point in history" :key="point.capturedAt"><strong>{{money(point.price)}}</strong><time>{{formatTime(point.capturedAt)}}</time></div></div><div v-else class="small-loading">暂无价格记录</div></el-dialog>
    <el-dialog v-model="purchaseOpen" title="确认已购买" width="650px"><p class="purchase-tip">只补充本次购买信息；系统会新建对应物品和主购买记录，心愿单将保留为“已购买”。</p><el-form label-position="top" class="dialog-form"><div class="dialog-grid"><el-form-item label="购买时间" required><el-date-picker v-model="purchaseForm.purchaseDate" value-format="YYYY-MM-DD" :shortcuts="dateShortcuts" /></el-form-item><el-form-item label="购买价格" required><el-input-number v-model="purchaseForm.price" :min="0" :precision="2" /></el-form-item><el-form-item label="购买平台"><el-select v-model="purchaseForm.platformId" clearable><el-option v-for="platform in platforms" :key="platform.id" :label="platform.name" :value="platform.id" /></el-select></el-form-item><el-form-item label="卖家/店铺"><el-input v-model="purchaseForm.seller" /></el-form-item></div><el-form-item label="购买链接"><el-input v-model="purchaseForm.productLink" placeholder="订单或商品链接（选填）" /></el-form-item><el-form-item label="购买附件"><div class="purchase-attachments"><AttachmentDropzone compact label="上传订单、发票或截图" hint="支持拖拽、点击或粘贴" @files="uploadPurchaseAttachments"/><span v-for="(attachment,index) in purchaseForm.attachments" :key="attachment" class="attachment-chip">附件 {{index+1}}<button type="button" @click="purchaseForm.attachments.splice(index,1)">×</button></span></div></el-form-item><el-form-item label="购买备注"><el-input v-model="purchaseForm.notes" type="textarea" /></el-form-item></el-form><template #footer><button class="secondary-button" @click="purchaseOpen=false">取消</button><PrimaryButton label="确认已购买" :loading="saving" @click="savePurchase" /></template></el-dialog>
    <el-drawer v-model="detailOpen" title="心愿详情" size="min(620px, calc(100vw - 24px))"><div v-if="selected" class="wish-detail"><img v-if="selected.imageUrl" :src="selected.imageUrl" :alt="selected.name"/><div class="detail-heading"><div><span class="tag" :class="{done:selected.status==='已购买'}">{{selected.status}}</span><h2>{{selected.name}}</h2><p>{{selected.brandName}} {{selected.model}}</p></div><button v-if="selected.convertedAssetId" class="secondary-button" @click="router.push(`/assets/${selected.convertedAssetId}`)">查看已购物品</button></div><dl><div><dt>目标价</dt><dd>{{money(selected.expectedPrice)}}</dd></div><div><dt>关注价格</dt><dd>{{money(selected.currentPrice)}}<small v-if="selected.lastPriceAt">更新于 {{formatTime(selected.lastPriceAt)}}</small></dd></div><div v-if="selected.status==='已购买'"><dt>购买时间</dt><dd>{{selected.purchasedAt||'—'}}</dd></div><div v-if="selected.status==='已购买'"><dt>购买价格差</dt><dd :class="{saving: (selected.purchasePriceDiff||0)<=0}">{{selected.purchasePriceDiff==null?'—':`${selected.purchasePriceDiff>0?'+':''}${money(selected.purchasePriceDiff)}`}}</dd></div><div><dt>心愿来源</dt><dd>{{selected.source||'未填写'}}</dd></div><div><dt>创建时间</dt><dd>{{formatTime(selected.createdAt)}}</dd></div><div class="wide"><dt>商品链接</dt><dd>{{selected.link||'未填写'}}</dd></div><div class="wide"><dt>备注</dt><dd>{{selected.notes||'未填写'}}</dd></div></dl><section class="detail-actions"><PrimaryButton v-if="selected.status!=='已购买'" label="标记已购买" @click="openPurchase(selected)" /><button class="secondary-button" @click="openHistory(selected)">查看价格历史</button></section></div></el-drawer>
    <el-dialog v-model="convertOpen" title="转为物品" width="620px"><el-form label-position="top" class="dialog-form"><div class="dialog-grid"><el-form-item label="物品名称" required><el-input v-model="convertForm.name" /></el-form-item><el-form-item label="分类" required><QuickCategorySelect v-model="convertForm.categoryId" :categories="categories" @created="addCategory" /></el-form-item><el-form-item label="状态"><el-select v-model="convertForm.status"><el-option label="使用中" value="使用中"/><el-option label="已闲置" value="已闲置"/></el-select></el-form-item><el-form-item label="购买日期"><el-date-picker v-model="convertForm.purchaseDate" value-format="YYYY-MM-DD" placeholder="请选择购买日期" :shortcuts="dateShortcuts" /></el-form-item></div></el-form><template #footer><button class="secondary-button" @click="convertOpen=false">取消</button><PrimaryButton label="创建物品" :loading="saving" @click="saveConvert" /></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage,ElMessageBox } from 'element-plus'
import { createWishlist,deleteWishlist,fetchPriceHistory,fetchWishlist,markWishlistPurchased,updateWishlist,updateWishlistPrice,convertWishlist } from '@/api/wishlist'; import { fetchBrands,fetchCategories,fetchPlatforms } from '@/api/settings'; import { uploadFile } from '@/api/files'; import type { AssetPayload,BrandItem,CategoryNode,PlatformItem,PricePoint,WishlistItem,WishlistPayload } from '@/types'
import PageHeader from '@/components/PageHeader.vue'; import PrimaryButton from '@/components/PrimaryButton.vue'; import AsyncState from '@/components/AsyncState.vue'; import QuickCategorySelect from '@/components/QuickCategorySelect.vue'; import QuickBrandSelect from '@/components/QuickBrandSelect.vue'; import AttachmentDropzone from '@/components/AttachmentDropzone.vue'; import plusIcon from '@/assets/icons/plus.svg'
const router=useRouter(); const items=ref<WishlistItem[]>([]),categories=ref<CategoryNode[]>([]),brands=ref<BrandItem[]>([]),platforms=ref<PlatformItem[]>([]),loading=ref(true),error=ref(''),saving=ref(false),uploading=ref(false),editorOpen=ref(false),priceOpen=ref(false),historyOpen=ref(false),convertOpen=ref(false),purchaseOpen=ref(false),detailOpen=ref(false),historyLoading=ref(false),editing=ref<WishlistItem>(),selected=ref<WishlistItem>(),currentPrice=ref(0),history=ref<PricePoint[]>([]),statusFilter=ref<'全部'|'未购买'|'已购买'>('全部'),keyword=ref(''),viewMode=ref<'list'|'thumbnail'>('list')
const wishForm=reactive<WishlistPayload>({name:'',priority:2}); const convertForm=reactive<AssetPayload>({name:'',categoryId:undefined as unknown as number,status:'使用中',purchases:[]}); const purchaseForm=reactive({purchaseDate:new Date().toISOString().slice(0,10),price:0,platformId:undefined as number|undefined,seller:'',productLink:'',attachments:[] as string[],notes:''})
const dateShortcuts=[{text:'今天',value:()=>new Date()}]
// Budget and price signals are derived from the current DTO so older wishlist rows with null price fields remain valid.
const pendingItems=computed(()=>items.value.filter(v=>v.status!=='已购买')); const purchasedItems=computed(()=>items.value.filter(v=>v.status==='已购买')); const sortedItems=computed(()=>items.value.filter(v=>{const query=keyword.value.trim().toLocaleLowerCase();const searchable=[v.name,v.source,v.brandName,v.model].filter(Boolean).join(' ').toLocaleLowerCase();return(statusFilter.value==='全部'||v.status===statusFilter.value)&&(!query||searchable.includes(query))}).sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime())); const totalBudget=computed(()=>pendingItems.value.reduce((n,v)=>n+Number(v.expectedPrice||0),0)); const highPriority=computed(()=>pendingItems.value.filter(v=>(v.priority||0)>=3).length); const priceCoverage=computed(()=>pendingItems.value.length?Math.round(pendingItems.value.filter(v=>v.currentPrice!=null).length/pendingItems.value.length*100):0)
const money=(n?:number)=>n==null?'—':`¥ ${Number(n).toLocaleString('zh-CN')}`; const initials=(n:string)=>n.slice(0,2); const priorityLabel=(n=1)=>['低优先级','低优先级','中优先级','高优先级'][n]||'低优先级'; const rate=(n?:number)=>n==null?'—':`${n>0?'↑':'↓'} ${Math.abs(n).toFixed(1)}%`; const formatTime=(v:string)=>new Date(v).toLocaleString('zh-CN'); const formatDate=(v:string)=>new Date(v).toLocaleDateString('zh-CN',{year:'numeric',month:'short',day:'numeric'})
const progressStyle=(value:number)=>({width:`${value}%`})
function insertCategory(nodes:CategoryNode[],category:CategoryNode):CategoryNode[]{if(!category.parentId)return[...nodes,category];return nodes.map(node=>node.id===category.parentId?{...node,children:[...(node.children||[]),category]}:{...node,children:insertCategory(node.children||[],category)})}
function addCategory(category:CategoryNode){categories.value=insertCategory(categories.value,category)}
function addBrand(brand:BrandItem){brands.value=[...brands.value,brand].sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'))}
async function load(){loading.value=true;error.value='';try{items.value=await fetchWishlist()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function openEditor(item?:WishlistItem){editing.value=item;Object.assign(wishForm,{name:'',priority:2,expectedPrice:undefined,currentPrice:undefined,categoryId:undefined,brandId:undefined,model:'',imageUrl:'',link:'',source:'',notes:''},item||{});editorOpen.value=true}
async function run(task:()=>Promise<unknown>,close:()=>void){saving.value=true;try{await task();ElMessage.success('操作已保存');close();await load()}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
const saveWish=()=>{if(!wishForm.name.trim()){ElMessage.warning('请输入名称');return}run(()=>editing.value?updateWishlist(editing.value.id,wishForm):createWishlist(wishForm),()=>editorOpen.value=false)}
function openPrice(item:WishlistItem){selected.value=item;currentPrice.value=item.currentPrice||0;priceOpen.value=true} const savePrice=()=>selected.value&&run(()=>updateWishlistPrice(selected.value!.id,currentPrice.value),()=>priceOpen.value=false)
async function uploadCover(files:File[]){const file=files[0];if(!file)return;uploading.value=true;try{wishForm.imageUrl=(await uploadFile(file)).url;ElMessage.success('心愿图片已上传')}catch(e){ElMessage.error((e as Error).message)}finally{uploading.value=false}}
async function openHistory(item:WishlistItem){selected.value=item;historyOpen.value=true;historyLoading.value=true;try{history.value=await fetchPriceHistory(item.id)}catch(e){ElMessage.error((e as Error).message)}finally{historyLoading.value=false}}
function openPurchase(item:WishlistItem){selected.value=item;Object.assign(purchaseForm,{purchaseDate:new Date().toISOString().slice(0,10),price:item.currentPrice||item.expectedPrice||0,platformId:undefined,seller:'',productLink:'',attachments:[],notes:''});purchaseOpen.value=true}
async function uploadPurchaseAttachments(files:File[]){try{const results=await Promise.all(files.map(uploadFile));purchaseForm.attachments.push(...results.map(result=>result.url));ElMessage.success(`已上传 ${results.length} 个附件`)}catch(e){ElMessage.error((e as Error).message)}}
const savePurchase=()=>{if(!selected.value)return;if(!selected.value.categoryId){ElMessage.warning('请先为心愿补充分类，才能创建已购物品');return}const wish=selected.value;const payload:AssetPayload={name:wish.name,categoryId:wish.categoryId as number,brandId:wish.brandId,model:wish.model,status:'使用中',purchaseDate:purchaseForm.purchaseDate,coverImageUrl:wish.imageUrl,notes:wish.notes,tagIds:wish.tags?.map(tag=>tag.id),purchases:[{type:'PRIMARY',price:purchaseForm.price,purchaseDate:purchaseForm.purchaseDate,platformId:purchaseForm.platformId,seller:purchaseForm.seller||undefined,productLink:purchaseForm.productLink||undefined,attachments:[...purchaseForm.attachments],notes:purchaseForm.notes||undefined,quantity:1}]};run(async()=>{const assetId=await markWishlistPurchased(wish.id,payload);purchaseOpen.value=false;detailOpen.value=false;await router.push(`/assets/${assetId}`)},()=>undefined)}
function openDetail(item:WishlistItem){selected.value=item;detailOpen.value=true}
async function remove(item:WishlistItem){try{await ElMessageBox.confirm(`确认删除“${item.name}”？`,'删除心愿',{type:'warning'});await run(()=>deleteWishlist(item.id),()=>undefined)}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
function openConvert(item:WishlistItem){selected.value=item;Object.assign(convertForm,{name:item.name,categoryId:item.categoryId,status:'使用中',purchaseDate:new Date().toISOString().slice(0,10),coverImageUrl:item.imageUrl,notes:item.notes,purchases:[]});convertOpen.value=true}
const saveConvert=()=>{if(!selected.value||!convertForm.categoryId){ElMessage.warning('请选择物品分类');return}run(async()=>{const id=await convertWishlist(selected.value!.id,convertForm);convertOpen.value=false;await router.push(`/assets/${id}`)},()=>undefined)}
onMounted(()=>{Promise.allSettled([fetchCategories(),fetchBrands(),fetchPlatforms()]).then(([categoryResult,brandResult,platformResult])=>{if(categoryResult.status==='fulfilled')categories.value=categoryResult.value;if(brandResult.status==='fulfilled')brands.value=brandResult.value;if(platformResult.status==='fulfilled')platforms.value=platformResult.value});load()})
</script>

